#!/usr/bin/env python3
"""Print count, min, max, mean for each numeric column of a CSV file.

Usage: stat.py <file.csv>
A column is numeric when every non-empty cell parses as a float.
"""
import csv
import sys


def main():
    if len(sys.argv) != 2:
        print(f"usage: {sys.argv[0]} <file.csv>", file=sys.stderr)
        return 2
    with open(sys.argv[1], newline="") as f:
        rows = list(csv.reader(f))
    if not rows:
        return 0
    header, data = rows[0], rows[1:]
    for i, name in enumerate(header):
        cells = [row[i].strip() for row in data if i < len(row) and row[i].strip() != ""]
        numbers = []
        for cell in cells:
            try:
                numbers.append(float(cell))
            except ValueError:
                numbers = []
                break
        if numbers:
            print(
                f"{name}: count={len(numbers)} min={min(numbers):g} "
                f"max={max(numbers):g} mean={sum(numbers) / len(numbers):g}"
            )
    return 0


if __name__ == "__main__":
    sys.exit(main())

